-- HEDA 013: admin, content, period budgets, verified academic QR and own inbox.
-- Run after 001-012 in SQL Editor. No administrator is assigned automatically.
begin;
do $$begin if to_regprocedure('public.heda_apply_own_action(uuid,jsonb)') is null then raise exception 'Primero ejecuta la migración 202610250012_assistant_actions.sql (y sus migraciones previas).';end if;end $$;
create table public.heda_staff(user_id uuid primary key references auth.users(id) on delete cascade);
create table public.heda_account_state(user_id uuid primary key references auth.users(id) on delete cascade,enabled boolean not null default true,updated_at timestamptz not null default now());
alter table public.heda_staff enable row level security;
alter table public.heda_account_state enable row level security;
revoke all on public.heda_staff,public.heda_account_state from public,anon,authenticated;
create function public.heda_account_active() returns boolean language sql stable security definer set search_path='' as $$ select auth.uid() is not null and not exists(select 1 from public.heda_account_state where user_id=auth.uid() and not enabled) $$;
create function public.heda_is_admin() returns boolean language sql stable security definer set search_path='' as $$ select public.heda_account_active() and exists(select 1 from public.heda_staff where user_id=auth.uid()) $$;
revoke all on function public.heda_account_active(),public.heda_is_admin() from public,anon;
grant execute on function public.heda_account_active(),public.heda_is_admin() to authenticated;
create table public.heda_audit(id bigint generated always as identity primary key,user_id uuid references auth.users(id) on delete cascade,actor uuid references auth.users(id) on delete set null,entity text not null,entity_id text,operation text not null,created_at timestamptz not null default now());
alter table public.heda_audit enable row level security;
revoke all on public.heda_audit from public,anon,authenticated;
grant select on public.heda_audit to authenticated;
create policy audit_own on public.heda_audit for select to authenticated using(user_id=auth.uid() and public.heda_account_active());
create function public.heda_guard_audit() returns trigger language plpgsql security definer set search_path='' as $$
declare row_data jsonb:=case when TG_OP='DELETE' then to_jsonb(old) else to_jsonb(new) end;own uuid;
begin
 if auth.uid() is not null and not public.heda_account_active() then raise exception 'Cuenta deshabilitada.' using errcode='42501';end if;
 own:=coalesce((row_data->>'user_id')::uuid,(case when TG_TABLE_NAME='profiles' then row_data->>'id' end)::uuid);
 -- No private field values, secrets, tokens, or full content in the audit.
 if own is not null and exists(select 1 from auth.users where id=own) then insert into public.heda_audit(user_id,actor,entity,entity_id,operation) values(own,auth.uid(),TG_TABLE_NAME,row_data->>'id',TG_OP);end if;
 return case when TG_OP='DELETE' then old else new end;
end $$;
revoke all on function public.heda_guard_audit() from public,anon,authenticated;
do $$declare t text;begin foreach t in array array['profiles','transactions','goals','budgets','recurring_movements','card_payments'] loop
 execute format('create policy heda_active_guard on public.%I as restrictive for all to authenticated using (public.heda_account_active()) with check (public.heda_account_active())',t);
 execute format('create trigger heda_guard_audit before insert or update or delete on public.%I for each row execute function public.heda_guard_audit()',t);
 end loop;end $$;
alter table public.budgets add column starts_on date,add column ends_on date;
alter table public.budgets add constraint budgets_valid_period check((starts_on is null and ends_on is null) or (starts_on is not null and ends_on is not null and starts_on<=ends_on and ends_on-starts_on<=366));
create table public.heda_lessons(id integer generated by default as identity primary key,title text not null check(length(btrim(title)) between 1 and 100),level text not null check(level in ('Básico','Intermedio')),description text not null check(length(description) between 1 and 4000),example text not null check(length(example) between 1 and 4000),tip text not null check(length(tip) between 1 and 2000),quiz jsonb not null check(jsonb_typeof(quiz)='object'),active boolean not null default true,updated_at timestamptz not null default now());
alter table public.heda_lessons enable row level security;
revoke all on public.heda_lessons from public,anon,authenticated;
grant select on public.heda_lessons to authenticated;
create policy lesson_read on public.heda_lessons for select to authenticated using(public.heda_account_active() and (active or public.heda_is_admin()));
create table public.heda_learning(user_id uuid not null references auth.users(id) on delete cascade,lesson_id integer not null references public.heda_lessons(id),completed_at timestamptz not null default now(),primary key(user_id,lesson_id));
alter table public.heda_learning enable row level security;
revoke all on public.heda_learning from public,anon,authenticated;
grant select,insert on public.heda_learning to authenticated;
create policy learning_own on public.heda_learning for all to authenticated using(user_id=auth.uid() and public.heda_account_active()) with check(user_id=auth.uid() and public.heda_account_active());
create table public.heda_notifications(user_id uuid not null references auth.users(id) on delete cascade,id text not null check(length(id)<=250),kind text not null,title text not null,body text not null,route text not null default 'Alertas',created_at timestamptz not null default now(),read_at timestamptz,primary key(user_id,id));
alter table public.heda_notifications enable row level security;
revoke all on public.heda_notifications from public,anon,authenticated;
grant select,insert on public.heda_notifications to authenticated;
grant update(read_at) on public.heda_notifications to authenticated;
create policy notification_own on public.heda_notifications for all to authenticated using(user_id=auth.uid() and public.heda_account_active()) with check(user_id=auth.uid() and public.heda_account_active() and length(title)<=160 and length(body)<=1000 and kind in ('Presupuestos','Pagos','Metas','Hábitos','Recomendaciones','Ethereum'));
create table public.heda_qr_requests(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,payload jsonb not null,created_at timestamptz not null default now(),expires_at timestamptz not null default now()+interval '7 days',status text not null default 'active' check(status in ('active','cancelled')));
create table public.heda_qr_receipts(id uuid primary key default gen_random_uuid(),request_id uuid not null references public.heda_qr_requests(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,movement_id uuid references public.transactions(id) on delete set null,registered_type text not null check(registered_type in ('income','expense')),created_at timestamptz not null default now(),unique(request_id,user_id));
alter table public.heda_qr_requests enable row level security;alter table public.heda_qr_receipts enable row level security;
revoke all on public.heda_qr_requests,public.heda_qr_receipts from public,anon,authenticated;
grant select on public.heda_qr_requests,public.heda_qr_receipts to authenticated;
create policy qr_request_own on public.heda_qr_requests for select to authenticated using(user_id=auth.uid() and public.heda_account_active());
create policy qr_receipt_participants on public.heda_qr_receipts for select to authenticated using(public.heda_account_active() and (user_id=auth.uid() or exists(select 1 from public.heda_qr_requests r where r.id=request_id and r.user_id=auth.uid())));
create function public.heda_qr_create(p_action jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare rid uuid;v numeric;d date;begin
 if not public.heda_account_active() then raise exception 'Cuenta no disponible.' using errcode='42501';end if;
 if jsonb_typeof(p_action) is distinct from 'object' or p_action->>'kind' is distinct from 'movement' or coalesce(p_action->>'type','') not in ('income','expense') or exists(select 1 from jsonb_object_keys(p_action) k where k not in ('kind','type','amount','category','description','date')) then raise exception 'Movimiento inválido.';end if;
 v:=(p_action->>'amount')::numeric;d:=(p_action->>'date')::date;
 if v is null or v<=0 or v>9999999999.99 or v<>round(v,2) or v='NaN'::numeric or d is null or d<date '1900-01-01' or d>date '2200-12-31' or coalesce(length(btrim(p_action->>'category')),0) not between 1 and 60 or length(coalesce(p_action->>'description',''))>300 then raise exception 'Datos inválidos.';end if;
 insert into public.heda_qr_requests(user_id,payload) values(auth.uid(),p_action) returning id into rid;
 insert into public.heda_audit(user_id,actor,entity,entity_id,operation) values(auth.uid(),auth.uid(),'qr',rid::text,'CREATE');
 return jsonb_build_object('id',rid);
end $$;
create function public.heda_qr_preview(p_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare r public.heda_qr_requests;u text;begin
 if not public.heda_account_active() then raise exception 'Cuenta no disponible.' using errcode='42501';end if;
 select * into r from public.heda_qr_requests where id=p_id;if not found then raise exception 'QR no disponible.';end if;
 select username into u from public.profiles where id=r.user_id;
 return jsonb_build_object('id',r.id,'action',r.payload,'sender',coalesce(u,'Usuario HEDA'),'createdAt',r.created_at,'expiresAt',r.expires_at,'status',case when r.status='cancelled' then 'cancelled' when r.expires_at<now() then 'expired' else 'active' end);
end $$;
create function public.heda_qr_accept(p_id uuid,p_type text) returns jsonb language plpgsql security definer set search_path='' as $$
declare r public.heda_qr_requests;receipt public.heda_qr_receipts;v_id uuid;begin
 if not public.heda_account_active() or p_type not in ('income','expense') or p_type is null then raise exception 'Cuenta o tipo no válido.' using errcode='42501';end if;
 select * into r from public.heda_qr_requests where id=p_id for update;if not found then raise exception 'QR no disponible.';end if;
 select * into receipt from public.heda_qr_receipts where request_id=p_id and user_id=auth.uid();
 if found then if receipt.registered_type<>p_type then raise exception 'Este QR ya fue registrado con otro tipo.';end if;return jsonb_build_object('ok',true,'id',coalesce(receipt.movement_id,receipt.id),'alreadyApplied',true);end if;
 if r.user_id=auth.uid() or r.status<>'active' or r.expires_at<now() or exists(select 1 from public.heda_account_state where user_id=r.user_id and not enabled) then raise exception 'QR propio, vencido, cancelado o emisor deshabilitado.';end if;
 insert into public.transactions(user_id,type,amount,category,description,transaction_date) values(auth.uid(),p_type,(r.payload->>'amount')::numeric,r.payload->>'category',r.payload->>'description',(r.payload->>'date')::date) returning id into v_id;
 insert into public.heda_qr_receipts(request_id,user_id,movement_id,registered_type) values(p_id,auth.uid(),v_id,p_type);
 insert into public.heda_audit(user_id,actor,entity,entity_id,operation) values(auth.uid(),auth.uid(),'qr',p_id::text,'IMPORT');
 return jsonb_build_object('ok',true,'id',v_id,'alreadyApplied',false);
end $$;
create function public.heda_qr_cancel(p_id uuid) returns void language plpgsql security definer set search_path='' as $$begin
 if not public.heda_account_active() then raise exception 'Cuenta no disponible.';end if;
 update public.heda_qr_requests set status='cancelled' where id=p_id and user_id=auth.uid();if not found then raise exception 'QR no disponible.';end if;
end $$;
create function public.heda_admin_users(p_offset integer default 0) returns jsonb language plpgsql security definer set search_path='' as $$begin
 if not public.heda_is_admin() then raise exception 'Solo administración.' using errcode='42501';end if;
 return coalesce((select jsonb_agg(x) from(select p.id,p.full_name,p.username,p.created_at,coalesce(s.enabled,true) enabled,exists(select 1 from public.heda_staff a where a.user_id=p.id) administrator from public.profiles p left join public.heda_account_state s on s.user_id=p.id order by p.created_at desc,p.id limit 100 offset greatest(0,least(p_offset,100000))) x),'[]'::jsonb);
end $$;
create function public.heda_admin_set_enabled(p_user uuid,p_enabled boolean) returns void language plpgsql security definer set search_path='' as $$begin
 if not public.heda_is_admin() or p_enabled is null or p_user=auth.uid() or exists(select 1 from public.heda_staff where user_id=p_user) then raise exception 'Operación no permitida.' using errcode='42501';end if;
 insert into public.heda_account_state(user_id,enabled) values(p_user,p_enabled) on conflict(user_id) do update set enabled=excluded.enabled,updated_at=now();
 insert into public.heda_audit(user_id,actor,entity,entity_id,operation) values(p_user,auth.uid(),'account',p_user::text,case when p_enabled then 'ENABLE' else 'DISABLE' end);
end $$;
create table public.heda_module_events(user_id uuid not null references auth.users(id) on delete cascade,module text not null,visit_day date not null default current_date,visits integer not null default 1,primary key(user_id,module,visit_day));
alter table public.heda_module_events enable row level security;
revoke all on public.heda_module_events from public,anon,authenticated;
create function public.heda_visit(p_module text) returns void language plpgsql security definer set search_path='' as $$begin
 if not public.heda_account_active() or p_module is null or p_module not in ('Inicio','Movimientos','IA','Reportes','Perfil','Ethereum','QR','EducacionFinanciera','Habitos','Alertas','Administracion') then raise exception 'Evento inválido.' using errcode='42501';end if;
 insert into public.heda_module_events(user_id,module) values(auth.uid(),p_module) on conflict(user_id,module,visit_day) do update set visits=least(1000,public.heda_module_events.visits+1);
end $$;
revoke all on function public.heda_visit(text) from public,anon;
grant execute on function public.heda_visit(text) to authenticated;
create function public.heda_admin_metrics() returns jsonb language plpgsql security definer set search_path='' as $$begin
 if not public.heda_is_admin() then raise exception 'Solo administración.' using errcode='42501';end if;
 return jsonb_build_object('usoModulos',(select coalesce(jsonb_object_agg(module,total),'{}'::jsonb) from(select module,sum(visits) total from public.heda_module_events group by module) m),'usuarios',(select count(*) from public.profiles),'cuentasDeshabilitadas',(select count(*) from public.heda_account_state where not enabled),'movimientos',(select count(*) from public.transactions),'metas',(select count(*) from public.goals),'presupuestos',(select count(*) from public.budgets),'qrCompartidos',(select count(*) from public.heda_qr_requests),'qrImportados',(select count(*) from public.heda_qr_receipts),'leccionesCompletadas',(select count(*) from public.heda_learning),'avisosGenerados',(select count(*) from public.heda_notifications),'consultasIA',(select coalesce(sum(chat_count+preview_count),0) from public.heda_ai_global_usage));
end $$;
create function public.heda_admin_save_lesson(p_id integer,p_lesson jsonb) returns integer language plpgsql security definer set search_path='' as $$declare rid integer;begin
 if not public.heda_is_admin() then raise exception 'Solo administración.' using errcode='42501';end if;
 if jsonb_typeof(p_lesson->'quiz'->'question') is distinct from 'string' or jsonb_typeof(p_lesson->'quiz'->'explanation') is distinct from 'string' or jsonb_typeof(p_lesson->'quiz'->'correct') is distinct from 'number' or jsonb_typeof(p_lesson->'quiz'->'options'->0) is distinct from 'string' or jsonb_typeof(p_lesson->'quiz'->'options'->1) is distinct from 'string' or coalesce(p_lesson->'quiz'->>'question','')='' or jsonb_typeof(p_lesson->'quiz'->'options') is distinct from 'array' or jsonb_array_length(p_lesson->'quiz'->'options')<>2 or coalesce(p_lesson->'quiz'->>'correct','') not in ('0','1') or coalesce(length(p_lesson->'quiz'->'options'->>0),0) not between 1 and 500 or coalesce(length(p_lesson->'quiz'->'options'->>1),0) not between 1 and 500 or coalesce(p_lesson->'quiz'->>'explanation','')='' or jsonb_typeof(p_lesson->'active') is distinct from 'boolean' then raise exception 'Cuestionario inválido.';end if;
 if p_id is null then insert into public.heda_lessons(title,level,description,example,tip,quiz,active) values(p_lesson->>'title',p_lesson->>'level',p_lesson->>'description',p_lesson->>'example',p_lesson->>'tip',p_lesson->'quiz',(p_lesson->>'active')::boolean) returning id into rid;
 else update public.heda_lessons set title=p_lesson->>'title',level=p_lesson->>'level',description=p_lesson->>'description',example=p_lesson->>'example',tip=p_lesson->>'tip',quiz=p_lesson->'quiz',active=(p_lesson->>'active')::boolean,updated_at=now() where id=p_id returning id into rid;if not found then raise exception 'Lección no disponible.';end if;end if;
 insert into public.heda_audit(user_id,actor,entity,entity_id,operation) values(auth.uid(),auth.uid(),'lesson',rid::text,'SAVE');return rid;
end $$;
revoke all on function public.heda_qr_create(jsonb),public.heda_qr_preview(uuid),public.heda_qr_accept(uuid,text),public.heda_qr_cancel(uuid),public.heda_admin_users(integer),public.heda_admin_set_enabled(uuid,boolean),public.heda_admin_metrics(),public.heda_admin_save_lesson(integer,jsonb) from public,anon;
grant execute on function public.heda_qr_create(jsonb),public.heda_qr_preview(uuid),public.heda_qr_accept(uuid,text),public.heda_qr_cancel(uuid),public.heda_admin_users(integer),public.heda_admin_set_enabled(uuid,boolean),public.heda_admin_metrics(),public.heda_admin_save_lesson(integer,jsonb) to authenticated;
insert into public.heda_lessons(id,title,level,description,example,tip,quiz) values(1,'Inflación','Básico','La inflación significa que los precios suben con el tiempo y tu dinero puede comprar menos cosas.','Si hoy compras una comida con $100, pero el próximo año esa misma comida cuesta $110, tu dinero perdió poder adquisitivo.','Guardar todo el dinero sin generar rendimiento puede hacer que pierda valor con el tiempo.','{"question": "¿Qué pasa con tu poder adquisitivo si los precios suben y tu ingreso sigue igual?", "options": ["Puedes comprar más cosas.", "Puedes comprar menos cosas."], "correct": 1, "explanation": "Con la misma cantidad de dinero, el aumento de precios reduce lo que puedes comprar."}'::jsonb);
insert into public.heda_lessons(id,title,level,description,example,tip,quiz) values(2,'Interés compuesto','Básico','Es cuando los rendimientos generan nuevos rendimientos. Es decir, tu dinero crece sobre lo que ya ganó.','Si inviertes $1,000 y ganas rendimiento, después el cálculo puede hacerse sobre el nuevo monto acumulado.','Mientras más tiempo mantengas una inversión o ahorro con rendimiento, mayor puede ser el efecto del interés compuesto.','{"question": "¿Sobre qué se calculan los nuevos rendimientos en el interés compuesto?", "options": ["Sobre el capital y los rendimientos acumulados.", "Siempre sobre el monto inicial únicamente."], "correct": 0, "explanation": "Los rendimientos que se reinvierten también pueden generar rendimientos."}'::jsonb);
insert into public.heda_lessons(id,title,level,description,example,tip,quiz) values(3,'Presupuesto personal','Básico','Un presupuesto te ayuda a decidir cuánto puedes gastar, ahorrar o separar para cada necesidad.','Puedes dividir tu dinero en comida, transporte, ahorro, pagos fijos y entretenimiento.','Un presupuesto no sirve para limitarte, sino para saber en qué se va tu dinero.','{"question": "¿Para qué te ayuda un presupuesto?", "options": ["Para gastar sin revisar tus ingresos.", "Para planear gastos y separar dinero para tus metas."], "correct": 1, "explanation": "Un presupuesto relaciona tus ingresos con tus necesidades, compromisos y metas."}'::jsonb);
insert into public.heda_lessons(id,title,level,description,example,tip,quiz) values(4,'Método 50/30/20','Intermedio','Es una estrategia para dividir tus ingresos: 50% necesidades, 30% deseos y 20% ahorro o pago de deuda.','Si recibes $10,000, podrías usar $5,000 en necesidades, $3,000 en gustos y $2,000 en ahorro o deudas.','Puedes ajustar los porcentajes según tu realidad, pero la idea es separar ahorro desde el inicio.','{"question": "En el ejemplo 50/30/20, ¿qué representa el 20%?", "options": ["Ahorro o pago de deuda.", "Todos tus gastos de entretenimiento."], "correct": 0, "explanation": "Es una guía flexible: puedes adaptar los porcentajes a tus posibilidades."}'::jsonb);
insert into public.heda_lessons(id,title,level,description,example,tip,quiz) values(5,'Fondo de emergencia','Básico','Es dinero separado para imprevistos, como enfermedad, reparación, pérdida de ingreso o emergencia familiar.','Una meta común es juntar entre 3 y 6 meses de tus gastos básicos.','Antes de invertir en activos riesgosos, conviene tener un fondo de emergencia.','{"question": "¿Para qué sirve un fondo de emergencia?", "options": ["Para comprar cualquier gusto del mes.", "Para cubrir imprevistos sin desajustar tus gastos habituales."], "correct": 1, "explanation": "Separa los imprevistos de los gastos que ya tenías planeados."}'::jsonb);
insert into public.heda_lessons(id,title,level,description,example,tip,quiz) values(6,'Riesgo y rendimiento','Intermedio','Generalmente, entre mayor rendimiento potencial, mayor riesgo. No existe ganancia segura sin riesgo.','Un instrumento estable puede dar menor rendimiento, mientras que un activo como Ethereum puede subir o bajar mucho.','Nunca inviertas dinero que necesitas para gastos básicos o emergencias.','{"question": "¿Un rendimiento potencial alto garantiza una ganancia?", "options": ["No, también debes considerar el riesgo de perder.", "Sí, si la promesa de rendimiento es muy alta."], "correct": 0, "explanation": "El rendimiento potencial no es una garantía. El valor de una inversión puede disminuir."}'::jsonb);
select setval(pg_get_serial_sequence('public.heda_lessons','id'),(select max(id) from public.heda_lessons));
create function public.heda_qr_history() returns jsonb language plpgsql security definer set search_path='' as $$begin
 if not public.heda_account_active() then raise exception 'Cuenta no disponible.' using errcode='42501';end if;
 return coalesce((select jsonb_agg(x order by x.created_at desc) from(
 select q.id,q.id request_id,'Compartido'::text kind,q.created_at,q.expires_at,q.payload,q.status,null::text registered_type,(select count(*) from public.heda_qr_receipts r where r.request_id=q.id) imports,(select string_agg('@'||coalesce(p.username,'usuario'),', ') from public.heda_qr_receipts r join public.profiles p on p.id=r.user_id where r.request_id=q.id) participant from public.heda_qr_requests q where q.user_id=auth.uid()
 union all
 select r.id,q.id,'Importado',r.created_at,q.expires_at,q.payload,'registered',r.registered_type,null::bigint,'@'||coalesce(p.username,'usuario') from public.heda_qr_receipts r join public.heda_qr_requests q on q.id=r.request_id join public.profiles p on p.id=q.user_id where r.user_id=auth.uid()
 order by created_at desc limit 60) x),'[]'::jsonb);
end $$;
revoke all on function public.heda_qr_history() from public,anon;
grant execute on function public.heda_qr_history() to authenticated;
alter function public.heda_apply_own_action(uuid,jsonb) rename to heda_apply_own_action_v12;
revoke all on function public.heda_apply_own_action_v12(uuid,jsonb) from public,anon,authenticated;
create function public.heda_apply_own_action(p_request_id uuid,p_action jsonb) returns jsonb language plpgsql security definer set search_path='' as $$begin
 if not public.heda_account_active() then raise exception 'Cuenta deshabilitada.' using errcode='42501';end if;
 return public.heda_apply_own_action_v12(p_request_id,p_action);end $$;
revoke all on function public.heda_apply_own_action(uuid,jsonb) from public,anon;
grant execute on function public.heda_apply_own_action(uuid,jsonb) to authenticated;
commit;
